fn test_strategy_adaptive_saturation() {
    common::runtime().block_on(async {
        // Adaptive strategy stops early when encountering saturation (duplicate content)
        let engine_config: CrawlConfig = serde_json::from_str(
            "{\"crawl_strategy\":\"best_first\",\"max_concurrent\":1,\"max_depth\":2,\"respect_robots_txt\":false}",
        )
        .expect("config should parse");
        let engine = create_engine(Some(engine_config)).expect("handle creation should succeed");
        let url = std::env::var("MOCK_SERVER_STRATEGY_ADAPTIVE_SATURATION").unwrap_or_else(|_| {
            let _ = common::mock_server_url();
            std::env::var("MOCK_SERVER_STRATEGY_ADAPTIVE_SATURATION").unwrap_or_else(|_| {
                format!(
                    "{}/fixtures/{}",
                    common::mock_server_url(),
                    "strategy_adaptive_saturation"
                )
            })
        });
        let result = crawl(&engine, &url).await.expect("call failed");
        assert!(!result.pages.is_empty(), "expected >= 1");
    });
}

